#[cfg(test)]
mod tests {
    use super::*;
    use dioxus::prelude::*;
    use dioxus_core::ReactiveContext;
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::Arc;

    /// Create a reactive context whose callback increments a shared counter every time it is marked
    /// dirty. Unlike [`ReactiveContext::new`], the counter is bumped on every notification (with no
    /// deduplication), so it can detect double-notifications.
    fn counting_reactive_context() -> (ReactiveContext, Arc<AtomicUsize>) {
        let count = Arc::new(AtomicUsize::new(0));
        let count_for_callback = count.clone();
        let rc = ReactiveContext::new_with_callback(
            move || {
                count_for_callback.fetch_add(1, Ordering::SeqCst);
            },
            ScopeId::ROOT,
            std::panic::Location::caller(),
        );
        (rc, count)
    }

    #[test]
    fn mark_dirty_marks_descendants_without_remarking_ancestors() {
        let dom = VirtualDom::new(|| rsx! {});
        dom.in_runtime(|| {
            dom.runtime().on_scope(ScopeId::ROOT, || {
                let subscriptions = StoreSubscriptions::new();

                // A deep subscriber at the root cares about everything in the store.
                let (root_rc, root_count) = counting_reactive_context();
                // A deep subscriber nested a couple levels down.
                let (child_rc, child_count) = counting_reactive_context();
                // A shallow subscriber even deeper that only cares about its own exact path.
                let (leaf_rc, leaf_count) = counting_reactive_context();

                root_rc.subscribe(subscriptions.deep_subscribers(&[]));
                child_rc.subscribe(subscriptions.deep_subscribers(&[1, 2]));
                leaf_rc.subscribe(subscriptions.shallow_subscribers(&[1, 2, 3]));

                // Writing to `[1]` should:
                // - notify the ancestor deep subscriber at `[]` (once),
                // - notify the descendant deep subscriber at `[1, 2]` (once),
                // - notify the descendant shallow subscriber at `[1, 2, 3]` (once).
                subscriptions.mark_dirty(&[1]);

                assert_eq!(root_count.load(Ordering::SeqCst), 1);
                assert_eq!(child_count.load(Ordering::SeqCst), 1);
                assert_eq!(leaf_count.load(Ordering::SeqCst), 1);
            });
        });
    }
