225	    /// Subscribe to a path and all of its children. This is a *deep* subscription: the reactive
226	    /// context is notified when the value at this path changes or when any nested value underneath it
227	    /// changes. This should be called any time we give out a raw reference to a store, because the
228	    /// user could read any level of the store.
229	    ///
230	    /// Unlike a shallow subscription, a deep subscription only needs to register a single node. Writes
231	    /// to descendant paths notify ancestor deep subscribers (see [`Self::mark_dirty`]), so a deep
232	    /// subscriber is reached even for descendant paths that did not exist when it subscribed.
233	    pub(crate) fn track_deep(&self, key: &[PathKey]) {
234	        if let Some(rc) = ReactiveContext::current() {
235	            let subscribers = self.deep_subscribers(key);
236	            rc.subscribe(subscribers);
