240	    /// Mark the node and all of its children as dirty, and also notify the deep subscribers of every
241	    /// ancestor of the node. Shallow subscribers of ancestors are intentionally left untouched since
242	    /// they only care about the exact value at their own path.
243	    pub(crate) fn mark_dirty(&self, key: &[PathKey]) {
244	        // Notify the deep subscribers of every ancestor. A write to a nested path is a change to each
245	        // of its parents, so any context that deeply subscribed to a parent should be re-run.
246	        self.mark_ancestors_dirty(key);
247	
248	        // Collect the paths of this node and all of its descendants, then notify both the shallow and
249	        // deep subscribers of each of them.
250	        let paths = {
251	            let read = &self.inner.read_unchecked();
252	            let Some(node) = read.root.get(key) else {
253	                return;
254	            };
255	            let mut paths = Vec::new();
256	            node.paths_under(key, &mut paths);
257	            paths
258	        };
259	        for path in paths {
