287	    /// Mark a single set of subscribers on a single node dirty.
288	    fn mark_subscribers_dirty(&self, key: &[PathKey], depth: SubscriptionDepth) {
289	        // We cannot hold the subscribers lock while calling mark_dirty, because mark_dirty can run user code which may cause a new subscriber to be added. If we hold the lock, we will deadlock.
290	        #[allow(clippy::mutable_key_type)]
291	        let mut subscribers = {
292	            let mut write = self.inner.write_unchecked();
293	            let Some(node) = write.root.get_mut(key) else {
294	                return;
295	            };
296	            std::mem::take(node.subscribers_mut(depth))
297	        };
298	        if subscribers.is_empty() {
299	            return;
300	        }
301	        subscribers.retain(|reactive_context| reactive_context.mark_dirty());
302	        // Extend the subscribers list instead of overwriting it in case a subscriber is added while reactive contexts are marked dirty
303	        let mut write = self.inner.write_unchecked();
304	        let Some(node) = write.root.get_mut(key) else {
305	            return;
306	        };
307	        node.subscribers_mut(depth).extend(subscribers);
308	    }
